     1→# ABOUTME: Test for Sea of Nodes IR generation - Chapter 1: Return constant
     2→# ABOUTME: Validates that parsing 'return 42;' generates correct IR graph with Start, Constant, and Return nodes
     3→
     4→use v5.42;
     5→use Test::More;
     6→use Test::Deep;
     7→
     8→# Test that we can load the IR modules
     9→use_ok('Chalk::IR::Node');
    10→use_ok('Chalk::IR::Graph');
    11→
    12→# Test manual IR graph construction for Chapter 1
    13→# This tests the IR infrastructure before we integrate with the parser
    14→subtest 'Manual IR graph construction for return 42' => sub {
    15→    my $graph = Chalk::IR::Graph->new();
    16→
    17→    # Create Start node (entry point)
    18→    my $start = Chalk::IR::Node->new(
    19→        id => 'node_0',
    20→        op => 'Start',
    21→        inputs => [],
    22→        attributes => { function => 'main' }
    23→    );
    24→    $graph->add_node($start);
    25→
    26→    # Create Constant node (value 42)
    27→    my $constant = Chalk::IR::Node->new(
    28→        id => 'node_1',
    29→        op => 'Constant',
    30→        inputs => ['node_0'],  # Non-semantic edge to Start for traversability
    31→        attributes => { value => 42, type => 'Int' }
    32→    );
    33→    $graph->add_node($constant);
    34→
    35→    # Create Return node (returns the constant)
    36→    my $return = Chalk::IR::Node->new(
    37→        id => 'node_2',
    38→        op => 'Return',
    39→        inputs => ['node_0', 'node_1'],  # Control from Start, data from Constant
    40→        attributes => {}
    41→    );
    42→    $graph->add_node($return);
    43→
    44→    # Verify graph structure
    45→    is($graph->entry, 'node_0', 'Entry node is Start');
    46→    is($graph->node_count, 3, 'Graph has 3 nodes');
    47→
    48→    # Verify Start node
    49→    my $start_node = $graph->get_node('node_0');
    50→    ok($start_node, 'Start node exists');
    51→    is($start_node->op, 'Start', 'Start node has correct op');
    52→    is(scalar @{$start_node->inputs}, 0, 'Start node has no inputs');
    53→    is($start_node->attributes->{function}, 'main', 'Start node has function name');
    54→
    55→    # Verify Constant node
    56→    my $const_node = $graph->get_node('node_1');
    57→    ok($const_node, 'Constant node exists');
    58→    is($const_node->op, 'Constant', 'Constant node has correct op');
    59→    cmp_deeply($const_node->inputs, ['node_0'], 'Constant connects to Start');
    60→    is($const_node->attributes->{value}, 42, 'Constant has value 42');
    61→    is($const_node->attributes->{type}, 'Int', 'Constant has type Int');
    62→
    63→    # Verify Return node
    64→    my $ret_node = $graph->get_node('node_2');
    65→    ok($ret_node, 'Return node exists');
    66→    is($ret_node->op, 'Return', 'Return node has correct op');
    67→    cmp_deeply($ret_node->inputs, ['node_0', 'node_1'],
    68→               'Return connects to Start (control) and Constant (data)');
    69→};
